import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"索引","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/index-drives.md","filePath":"zh-CN/user-guide/settings/index-drives.md","lastUpdated":1786770456000}'),n={name:"zh-CN/user-guide/settings/index-drives.md"};function a(i,o,l,d,g,c){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h1><p>按顺序共五个 Tab：<strong>本地驱动器</strong>、<strong>网络驱动器</strong>、<strong>WSL</strong>（只在检测到发行版时才出现）、<strong>文件夹</strong>、<strong>排除规则</strong>。</p><h2 id="本地驱动器" tabindex="-1">本地驱动器 <a class="header-anchor" href="#本地驱动器" aria-label="Permalink to &quot;本地驱动器&quot;">​</a></h2><ul><li>顶部状态卡片汇总已索引的驱动器数量与项目数量，并提供<strong>重建索引</strong>按钮做全量重扫描。</li><li>每个本地驱动器一行：<strong>启用/禁用复选框</strong>、驱动器名称、文件系统（NTFS/ReFS 等）、当前状态、已索引项目数，以及每行独立的<strong>重建</strong>/<strong>移除</strong>操作——重建进行中时还会出现<strong>停止</strong>操作（真正的 NTFS 走 $MFT 扫描没有安全的中断点，是唯一的例外）。</li><li>NTFS 和 ReFS 磁盘通过 Windows USN 日志持续跟踪变更；其他本地文件系统（FAT32、exFAT 等）没有日志可读，改为直接监听文件系统变化。不管哪种方式，手动重建都很少需要，但如果发现内容不同步，随时可以用它——如果重建过程中被中断（手动停止，或者应用/服务中途重启），下次会从中断的地方继续，而不是从头再来。</li></ul><p>已启用驱动器的选择会被严格保留：如果清空全部复选框，本地磁盘索引会保持禁用，不会再悄悄把所有驱动器选回来。对于旧版本中以“空列表”表示“全部驱动器”的现有设置，升级时会进行一次迁移，避免索引被意外禁用。</p><p>重建期间搜索照常可用。正在重建的驱动器会继续用它此前的索引应答，直到新索引就绪；其余驱动器完全不受影响——重建不会让你面对一个空的结果列表。</p><h2 id="网络驱动器" tabindex="-1">网络驱动器 <a class="header-anchor" href="#网络驱动器" aria-label="Permalink to &quot;网络驱动器&quot;">​</a></h2><ul><li>与本地驱动器相同的状态卡片和<strong>重建索引</strong>按钮。</li><li>每个已映射的网络驱动器一行：启用复选框、路径/名称、状态（索引中 / 就绪 / 已缓存 / 失败 / 等待中 / 已连接）、项目数，以及<strong>刷新模式</strong>下拉框： <ul><li><strong>手动</strong> —— 只在手动触发（重建索引）时刷新。</li><li><strong>每 15 分钟</strong></li><li><strong>每小时</strong></li><li><strong>每天</strong></li></ul></li></ul><p>网络共享没有本地 NTFS 卷那样的变更日志可供监听，所以采用定时刷新而不是实时更新。扫描引擎内置了分支祖先路径栈与符号链接环路检测机制，即使 NAS/SMB 共享上存在指向父级目录的软链接或重解析点，也能自动拦截死循环，确保索引数量准确不膨胀。</p><h2 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h2><p>只有检测到至少一个 WSL 发行版时才会出现——形态和网络驱动器一样（状态卡片、<strong>重建索引</strong>按钮，每个发行版一行，显示状态/项目数/<strong>刷新模式</strong>）。发行版是自动检测的，没有手动“添加”这一步。</p><p>WSL 搜索结果始终来自当前索引。搜索时 Lertaro 不会探测 WSL 文件系统，因此结果会反映已索引的状态，直到下一次刷新或重建；打开或预览结果仍可能访问文件，因为那是用户明确发起的操作。</p><h2 id="文件夹" tabindex="-1">文件夹 <a class="header-anchor" href="#文件夹" aria-label="Permalink to &quot;文件夹&quot;">​</a></h2><p>单独索引任意文件夹，而不是整个驱动器或共享——适合只想索引某一个子目录，而不想把这个盘/共享下的其他内容也纳入索引的场景。</p><ul><li><strong>添加文件夹</strong>按钮会打开文件夹选择器；<strong>重建索引</strong>按钮会重新扫描列表中的所有文件夹。</li><li>每个已添加的文件夹一行：启用复选框、路径、状态、项目数，以及和网络驱动器一样的<strong>刷新模式</strong>下拉框（手动 / 每 15 分钟 / 每小时 / 每天）——文件夹和网络共享一样按计划扫描，而不是持续实时跟踪。</li><li>文件夹选择器也支持直接选一个 <strong>UNC 网络共享路径</strong>（比如 <code>\\\\server\\share</code>，或者它里面的子目录）——在选择器里通过“网络”浏览过去即可，适合只想索引某一个共享或子目录，而不想把整台服务器都加成映射的网络驱动器。</li></ul><h2 id="排除规则" tabindex="-1">排除规则 <a class="header-anchor" href="#排除规则" aria-label="Permalink to &quot;排除规则&quot;">​</a></h2><p>三个子 Tab，形态完全一致：一个单条输入框 + <strong>添加</strong>按钮，一个可编辑/删除每一条规则的列表，以及一个批量多行文本框，配 <strong>从列表生成</strong> / <strong>应用到列表</strong> 两个按钮，用来一次性编辑全部规则。</p><ul><li><strong>路径排除</strong> —— 完整路径或环境变量（例如 <code>D:\\Cache</code>、<code>%ProgramData%</code>）。</li><li><strong>Glob 通配符</strong> —— <code>*</code>（文件名中任意字符）、<code>?</code>（单个字符）、<code>**</code>（递归目录）。示例：<code>*.tmp</code>、<code>**/node_modules/**</code>、<code>bin/**</code>。</li><li><strong>正则表达式</strong> —— 针对路径/文件名做部分匹配的任意正则。示例：<code>^\\.</code>（隐藏文件）、<code>~$</code>（Office 临时文件）、<code>\\.git\\</code>。</li></ul><p>排除规则对本地、网络、文件夹索引都生效，应用排除规则的改动后，网络驱动器/文件夹会自动重新扫描。</p>',19)])])}const p=t(n,[["render",a]]);export{u as __pageData,p as default};
